using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
class WorkbenchAccessTests {
 static int checks,failures;
 static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(o);}
 static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Invoke(o,args);}
 static void Check(string n,bool ok){checks++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);if(!ok)failures++;}
 static T Find<T>(DependencyObject root,Func<T,bool> match)where T:DependencyObject{var v=root as T;if(v!=null&&match(v))return v;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var f=Find<T>(VisualTreeHelper.GetChild(root,i),match);if(f!=null)return f;}return null;}
 static void Click(DependencyObject root,string caption){var b=Find<Button>(root,x=>Convert.ToString(x.Content)==caption);if(b==null)throw new Exception("Missing button "+caption);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 static void Toggle(DependencyObject root,string caption){var b=Find<CheckBox>(root,x=>Convert.ToString(x.Content)==caption);if(b==null)throw new Exception("Missing switch "+caption);b.IsChecked=!(b.IsChecked==true);b.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));}
 static void Contact(object pet,string action){double start=(double)Get(pet,"footballKickStart");double duration=FootballWorld.ContactTime(action);for(double t=1.0/120;t<duration+.009;t+=1.0/120)Call(pet,"TickFootball",start+t,1.0/120);}
 static void Shot(Window w,string name){w.UpdateLayout();var e=(FrameworkElement)w.Content;var bm=new RenderTargetBitmap((int)e.ActualWidth,(int)e.ActualHeight,96,96,PixelFormats.Pbgra32);bm.Render(e);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bm));using(var f=File.Create(name))png.Save(f);}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();var runtime=(SkillRuntime)Get(pet,"skills");runtime.Engine.SetWorkEnd(true,1087,1);Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.UpdateLayout();
 var nav=(IDictionary)Get(w,"navigation");Check("work end directly listed in sidebar",nav.Contains("下班倒计时"));if(!nav.Contains("下班倒计时"))throw new Exception("No direct work-end navigation");
 Click(w,"下班倒计时");w.UpdateLayout();Check("direct route shows work-end editor",Find<Button>(w,b=>Convert.ToString(b.Content)=="保存下班设置")!=null);Check("work end separated from generic reminder form",Find<Button>(w,b=>Convert.ToString(b.Content)=="添加倒计时")==null);
 var skills=Get(pet,"skillsWindow");var editors=(IList)Get(skills,"endEditors");var hour=(ComboBox)Get(editors[0],"Hour");var minute=(ComboBox)Get(editors[0],"Minute");Check("legacy time preserved",hour.Text=="18"&&minute.Text=="07");Check("time selectors editable",hour.IsEditable&&minute.IsEditable&&hour.Items.Count==24&&minute.Items.Count==60);hour.ApplyTemplate();minute.ApplyTemplate();Check("theme renders actual editable textbox",hour.Template.FindName("PART_EditableTextBox",hour) as TextBox!=null);
 hour.Text="13";minute.Text="09";Click(w,"保存下班设置");Check("manual digits saved",runtime.Engine.WorkEndSlots()[0].MinuteOfDay==789);hour.SelectedIndex=17;minute.SelectedIndex=45;Click(w,"保存下班设置");Check("dropdown choice saved",runtime.Engine.WorkEndSlots()[0].MinuteOfDay==1065);
 hour.Text="25";bool invalid=false;try{Call(skills,"ReadWorkEndTime",hour,minute);}catch(TargetInvocationException e){invalid=e.InnerException is ArgumentException;}Check("invalid hour rejected",invalid);hour.Text="17";minute.Text="60";invalid=false;try{Call(skills,"ReadWorkEndTime",hour,minute);}catch(TargetInvocationException e){invalid=e.InnerException is ArgumentException;}Check("invalid minute rejected",invalid);minute.Text="45";
 Shot(w,Path.Combine(args[0],"work-end-a.png"));Click(w,"B · 月下基德");w.UpdateLayout();Check("theme switch keeps time input",hour.Text=="17"&&minute.Text=="45");Shot(w,Path.Combine(args[0],"work-end-b.png"));w.BackPage();Check("back returns overview",Convert.ToString(Get(w,"page"))=="总览");
 w.ShowPage("提醒");w.UpdateLayout();Check("generic reminders keep their own page",Find<Button>(w,b=>Convert.ToString(b.Content)=="添加倒计时")!=null&&Find<Button>(w,b=>Convert.ToString(b.Content)=="保存下班设置")==null);
 w.ShowPage("动作与移动");w.UpdateLayout();var voice=(VoiceRuntime)Get(pet,"voices");Toggle(w,"待机与漫游语音");Check("idle toggle updates runtime",!(bool)Get(voice.Settings,"Ambient"));Check("idle switch blocks automatic playback",!voice.PlayAmbient("travel",false));Check("idle switch preserves other audio",voice.Settings.Enabled&&voice.Settings.Interactions);using(var manual=new VoiceRuntime(AppDomain.CurrentDomain.BaseDirectory)){manual.Settings.Ambient=false;Check("manual preview bypasses idle mute",manual.Preview(manual.Catalog.Clips[0]));}using(var automatic=new VoiceRuntime(AppDomain.CurrentDomain.BaseDirectory)){automatic.Settings.Ambient=true;bool accepted=automatic.PlayAmbient("travel",false);automatic.Settings.Ambient=false;automatic.Apply();Check("switch immediately stops active idle audio",accepted&&!automatic.Playing);}voice.Apply();using(var restored=new VoiceRuntime(AppDomain.CurrentDomain.BaseDirectory))Check("idle switch persists",!(bool)Get(restored.Settings,"Ambient"));
 w.ShowPage("原声配音");w.UpdateLayout();var ambient=Find<CheckBox>(w,c=>Convert.ToString(c.Content)=="待机与漫游语音");Check("voice page agrees with idle switch",ambient!=null&&ambient.IsChecked==false);Toggle(w,"待机与漫游语音");w.ShowPage("动作与移动");w.UpdateLayout();Check("movement page reflects voice page changes",Find<CheckBox>(w,c=>Convert.ToString(c.Content)=="待机与漫游语音").IsChecked==true);
 Toggle(w,"足球保持人物所在高度");Check("football toggle updates persisted preference",(bool)Get(pet,"footballLevel"));Check("football flag written to stable settings",File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"settings.ini")).Contains("footballLevel=true"));typeof(ConanPet).GetField("footballLevel",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(pet,false);Call(pet,"ReadPreferences");Check("football setting restored from saved data",(bool)Get(pet,"footballLevel"));Call(pet,"StartFootball","volley");Contact(pet,"volley");var ball=(FootballWorld)Get(pet,"football");Check("volley enables horizontal flight at contact",(bool)Get(ball,"HorizontalFlight"));double y=ball.Y;for(int i=0;i<300;i++)ball.Step(.016,0,0,1200,1000);Check("horizontal ball stays at shot height",Math.Abs(ball.Y-y)<.001);Check("horizontal ball reflects off screen edge",ball.X>=ball.Radius&&ball.X<=1200-ball.Radius);var wallBall=new FootballWorld();wallBall.Throw(580,250,0,0,12);wallBall.Strike(400,-100,true);for(int i=0;i<30;i++)wallBall.Step(.016,0,0,600,800);Check("horizontal shot reflects without losing height",wallBall.VX<0&&Math.Abs(wallBall.Y-250)<.001);
 Call(pet,"StartFootball","flick");Contact(pet,"flick");Check("upward flick retains its vertical trajectory",!(bool)Get(ball,"HorizontalFlight")&&ball.VY<0);Call(pet,"StopFootball");Call(pet,"StartFootball","bicycle");Contact(pet,"bicycle");Check("bicycle shot also uses horizontal flight",ball.HorizontalFlight);Call(pet,"StopFootball");Toggle(w,"足球保持人物所在高度");Call(pet,"StartFootball","volley");Contact(pet,"volley");Check("disabled football switch restores gravity",!(bool)Get(ball,"HorizontalFlight"));Call(pet,"StopFootball");
 Toggle(w,"足球保持人物所在高度");w.ShowPage("动作演示");w.UpdateLayout();Check("football action page exposes same toggle",Find<CheckBox>(w,c=>Convert.ToString(c.Content)=="足球保持人物所在高度").IsChecked==true);Shot(w,Path.Combine(args[0],"football-controls.png"));
 var p=(FrameworkElement)w.Content;Check("all leaf functions have direct sidebar routes",new[]{"下班倒计时","专注","待办计划","提醒","健康","文件搜索","快捷入口","文件观察","证物卡","磁盘与电池","便签","文本","剪贴板","桌面工具","语音与快捷键","动作与移动","动作演示","原声配音","性能监控","Codex状态","进程监控","系统与网络","通知中心","通知记录","数据与备份"}.All(n=>nav.Contains(n)));
 foreach(string route in nav.Keys){w.ShowPage(route);w.UpdateLayout();}Check("all sidebar pages open without nesting or parent conflicts",true);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"access-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");Console.WriteLine("Checks: "+checks+" Failures: "+failures);return failures==0?0:1;}
}
